 @SubscribeEvent public static void start(net.neoforged.neoforge.event.server.ServerStartedEvent event){if(!Boolean.getBoolean("vandorlabs.digitizeChecks"))return;try{world=event.getServer().overworld();for(int x=1;x<=2;x++)for(int z=1;z<=2;z++){world.setChunkForced(x,z,true);world.getChunk(x,z);}actor=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(new UUID(0,211130),"NativeDigitize"));actor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);actor.setPos(31.5,120,27.5);actor.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.DIAMOND_PICKAXE));input=input();chip=chip();NativeBlockRecipeChecks.run(world);packets();if(read()){need(root()!=null&&!root().inert()&&root().formed()&&root().mode()==1&&root().processing(),"actual cold partial digitize owner");need(ItemStack.matches(input,root().getItem(0))&&ItemStack.matches(chip,root().getItem(3)),"cold original input/chip exact");need(root().buildProgress()>0&&root().buildProgress()<1,"cold partial RF restored");savedProgress=root().buildProgress();stage=2;return;}var block=NativeBuilderBindings.CORES.get("synthesis_tower");world.setBlock(P,block.defaultBlockState(),3);var d=root().design();var layout=new com.vandorlabs.machines.CoreLayout(d.width(),d.height(),d.depth(),Direction.NORTH.get3DDataValue(),0,0);for(int x=0;x<d.width();x++)for(int y=0;y<d.height();y++)for(int z=0;z<d.depth();z++){var at=P.offset(layout.x(x,z),y,layout.z(x,z));if(!at.equals(P))world.setBlock(at,layout.frame(x,y,z)?NativeBuilderFormation.matter().defaultBlockState():Blocks.AIR.defaultBlockState(),3);}need(NativeBuilderTransactions.request(root(),actor,true),"real async Tower formation requested");stage=1;}catch(Throwable bad){fail(bad);}}
 private static void packets(){var buffer=new RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),world.registryAccess());var edit=new NativeBuilderEdit(3,P,0,5,ChannelList.EMPTY);NativeBuilderPayload.CODEC.encode(buffer,new NativeBuilderPayload(edit));need(buffer.readableBytes()==15&&NativeBuilderPayload.CODEC.decode(buffer).edit().equals(edit),"unchanged native15-byte settings roundtrip/dynamicindex5");buffer.release();boolean rejected=false;try{new NativeBuilderEdit(3,P,0,6,ChannelList.EMPTY);}catch(IllegalArgumentException yes){rejected=true;}need(rejected,"selection upper bound before allocation");}
 private static void malformed(){var idle=root().saveWithoutMetadata(world.registryAccess());var explicit=idle.copy();explicit.getCompound("Synthesis").putInt("Mode",0);var old=new NativeBuilderEntity(P,root().getBlockState());old.setLevel(world);old.loadWithComponents(explicit,world.registryAccess());need(!old.inert()&&NativeBuilderData.sameSnapshots(explicit,old.saveWithoutMetadata(world.registryAccess())),"absent/explicitdefaultmode compatibility");for(int fault=0;fault<8;fault++){var tag=idle.copy();var work=tag.getCompound("Synthesis");switch(fault){case 0->work.putInt("Mode",2);case 1->work.putString("Mode","1");case 2->{work.putInt("Mode",1);work.putBoolean("Active",true);work.putInt("Work",100);work.put("DigitizeBlock",input.save(world.registryAccess()));work.putByteArray("DigitizeChipHash",new byte[31]);}case 3->work.put("DigitizeBlock",input.save(world.registryAccess()));case 4->{work.putInt("Mode",1);work.putBoolean("Active",true);work.putInt("Work",100);work.put("DigitizeBlock",new ItemStack(Items.CHEST).save(world.registryAccess()));work.putByteArray("DigitizeChipHash",new byte[32]);}case 5->work.put("ProductionTemplate",input.save(world.registryAccess()));case 6->work.putInt("FutureOwnership",1);case 7->tag.put("BuilderInput",input.save(world.registryAccess()));}var copy=new NativeBuilderEntity(P,root().getBlockState());copy.setLevel(world);copy.loadWithComponents(tag,world.registryAccess());need(copy.inert(),"malformed job inert fault="+fault);var retained=copy.saveWithoutMetadata(world.registryAccess());for(String key:tag.getAllKeys())need(Objects.equals(tag.get(key),retained.get(key)),"full original retained "+fault+"/"+key);}}
