  need(owner.batteryCapacity()==0&&owner.batteryEnergy()==0,"oversized probe has no batteries");oversized=NativeCredentialItems.ownedCopy(chip);var tag=oversized.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();tag.putByteArray("OversizedAdmissionProbe",new byte[70*1024]);oversized.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));need(NativeCredentialItems.accepts(oversized,true),"oversized probe is accepted credential, not invalid chip type");need(oversized.save(world.registryAccess()).sizeInBytes()>64*1024,"encoded probe exceeds Digitize admission bound");owner.configureRedstone(0,ChannelList.EMPTY);owner.setItem(0,input.copy());oversizedTotalSerializations=oversizedSerializations=NativeSynthesisRuntime.admissionSerializations;owner.setItem(3,NativeCredentialItems.ownedCopy(oversized));oversizedTicks=0;
