  if(stage==10){need(owner.processing(),"valid chip replacement invalidates oversized admission cache and starts real work");need(NativeSynthesisRuntime.admissionSerializations-validReplacementSerializations==1,"valid replacement serialized once and warm active work reuses admission");need(ItemStack.matches(owner.getItem(0),input)&&ItemStack.matches(owner.getItem(3),chip),"input/chip remain original during work");if(owner.buildProgress()<.3)return;need(owner.processing()&&!owner.setMode(0),"active mode cannot switch");owner.configureRedstone(1,ChannelList.EMPTY);var tag=owner.saveWithFullMetadata(world.registryAccess());need(tag.getCompound("Synthesis").getByteArray("DigitizeChipHash").length==32,"bounded private identity");need(!owner.getUpdateTag(world.registryAccess()).toString().contains("DigitizeChipHash")&&!owner.getUpdateTag(world.registryAccess()).toString().contains("PrivateDigitizeProbe"),"public preview excludes private job/chip data");var detached=new NativeBuilderEntity(P,owner.getBlockState());detached.loadWithComponents(tag,world.registryAccess());need(!detached.inert()&&NativeBuilderData.sameSnapshots(tag,detached.saveWithFullMetadata(world.registryAccess())),"detached partialjob exact roundtrip");restoredIdentity(tag);world.getServer().saveEverything(false,true,true);finish("save");return;}
